CREATE OR REPLACE VIEW BRICKSURANCE.semantics.enrichment_coverage
COMMENT = 'A completeness readout of the enrichment domain - for each external source, how many records exist and how many distinct subjects they cover. A data-quality view: how much of the book actually carries each risk signal, so gaps are visible rather than assumed. Grain: One row per enrichment source.'
AS
SELECT 'motor_telematics_aggregate' AS enrichment_source,
       'policy' AS subject_kind,
       COUNT(*) AS record_count,
       COUNT(DISTINCT policy_id) AS subject_count
FROM BRICKSURANCE.enrichment.motor_telematics_aggregate
UNION ALL
SELECT 'policy_demographics', 'policy', COUNT(*), COUNT(DISTINCT policy_id)
FROM BRICKSURANCE.enrichment.policy_demographics
UNION ALL
SELECT 'credit_bureau_summary', 'party', COUNT(*), COUNT(DISTINCT party_id)
FROM BRICKSURANCE.enrichment.credit_bureau_summary
UNION ALL
SELECT 'sanctions_screen', 'party', COUNT(*), COUNT(DISTINCT party_id)
FROM BRICKSURANCE.enrichment.sanctions_screen
UNION ALL
SELECT 'geospatial_hazard', 'location', COUNT(*), COUNT(DISTINCT location_key)
FROM BRICKSURANCE.enrichment.geospatial_hazard
UNION ALL
SELECT 'postcode_enrichment', 'postcode', COUNT(*), COUNT(DISTINCT postcode)
FROM BRICKSURANCE.enrichment.postcode_enrichment
UNION ALL
SELECT 'market_pricing_benchmark', 'segment', COUNT(*),
       COUNT(DISTINCT CONCAT(line_of_business_code, ':', COALESCE(segment, '')))
FROM BRICKSURANCE.enrichment.market_pricing_benchmark;
